import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.DTdEDYjJ.js";const r="/openbot/diagrams/dsh-architecture-analysis.png",c="/openbot/diagrams/bot-studio-layers.png",g=JSON.parse('{"title":"执行内核与健康检测","description":"","frontmatter":{},"headers":[],"relativePath":"guide/harness.md","filePath":"guide/harness.md"}'),s={name:"guide/harness.md"};function i(l,e,n,h,p,b){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="执行内核与健康检测" tabindex="-1">执行内核与健康检测 <a class="header-anchor" href="#执行内核与健康检测" aria-label="Permalink to &quot;执行内核与健康检测&quot;">​</a></h1><p>Harness 负责一次任务的模型与工具循环。OpenBot 通过薄 Adapter 接入驱动，自己持有 Bot 身份、记忆边界、权限、屏幕、任务与责任记录。切换内核不会增加权限，也不会重跑失败任务。</p><p>先完成<a href="/openbot/guide/models.html">模型配置</a>，再为需要工具的 API Bot 选择执行路径。</p><h2 id="当前内核" tabindex="-1">当前内核 <a class="header-anchor" href="#当前内核" aria-label="Permalink to &quot;当前内核&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>驱动 ID</th><th>实现与用途</th></tr></thead><tbody><tr><td>跟随应用默认</td><td>空值</td><td>当前默认 DSH，可由明确的启动配置调整</td></tr><tr><td>DeepSeek Harness</td><td><code>dsh</code></td><td>已打包的 Bot runtime，OpenBot Adapter <code>0.6.0</code>；API Bot 默认路径</td></tr><tr><td>Pi Agent</td><td><code>pi</code></td><td><code>@earendil-works/pi-agent-core</code> <code>1.3.0</code>，Adapter <code>0.1.0</code>；显式辅助路径</td></tr><tr><td>OpenBot 工具循环</td><td><code>legacy</code></td><td>原有兼容循环，版本跟随 OpenBot</td></tr></tbody></table><p>DeepSeek模型API和DSH是两件事。默认使用DSH不要求绑定某个模型提供商；模型仍由每个Bot自己的连接决定。未知驱动报错，加载或执行失败不静默改用另一内核。</p><h2 id="为一个-bot-选择内核" tabindex="-1">为一个 Bot 选择内核 <a class="header-anchor" href="#为一个-bot-选择内核" aria-label="Permalink to &quot;为一个 Bot 选择内核&quot;">​</a></h2><ol><li>确认 Bot 的模型连接与模型名。</li><li>在该 Bot 的设置或高级设置中选择执行内核；留空跟随应用默认。</li><li>按任务需要明确开启工具，保存后开始新任务。</li><li>主动检测当前组合，再用范围小、结果可检查的任务验证实际能力。</li></ol><p>API Bot分别拥有自己的runtime profile、工作目录和运行锁。已绑定的CLI/ACP沿用自己的执行器和登录上下文，不会因为选择API内核就自动改变其订阅或权限。</p><h2 id="插件和能力的边界" tabindex="-1">插件和能力的边界 <a class="header-anchor" href="#插件和能力的边界" aria-label="Permalink to &quot;插件和能力的边界&quot;">​</a></h2><p>DSH插件按Bot profile装配，使用已审核的本地配置，不等于任意上游插件都能一键安装或获得宿主权限。OpenBot继续校验工具参数、审批、取消和副作用边界。</p><p>本版没有通用Harness在线升级市场。更新上游框架时固定版本、锁文件和Adapter契约，分别记录提供商与适配器版本，先验证拒绝、取消、停止、接管与不重放，再发布。</p><h2 id="验证当前组合" tabindex="-1">验证当前组合 <a class="header-anchor" href="#验证当前组合" aria-label="Permalink to &quot;验证当前组合&quot;">​</a></h2><p>在Bot设置中主动点击模型与执行器检测。这会发送实际最小请求，可能使用服务额度。安装成功、版本号正常或发现登录文件都不能证明订阅可用。</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>未检测</td><td>当前组合没有有效检测记录</td></tr><tr><td>检测中</td><td>请求尚未完成，可取消</td></tr><tr><td>已验证可用</td><td>当时的模型和执行路径完成检测</td></tr><tr><td>不可用</td><td>请求失败或未符合预期</td></tr><tr><td>需重新检测</td><td>配置已变化或记录已过期</td></tr></tbody></table><p>记录有效期30分钟。地址、Key、模型、Harness或Adapter版本变化后，旧结果不能沿用。检测回执不保存凭据、提示词或回复正文；通过检测也不授予工具权限或证明浏览器业务已完成。</p><h2 id="开发者契约" tabindex="-1">开发者契约 <a class="header-anchor" href="#开发者契约" aria-label="Permalink to &quot;开发者契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>责任</th><th>持有方</th></tr></thead><tbody><tr><td>单次模型和工具调度</td><td>DSH/Pi Adapter 或兼容循环</td></tr><tr><td>工具清单、校验、授权与拒绝去重</td><td>OpenBot共享工具策略</td></tr><tr><td>步数、超时、取消与重复调用限制</td><td>OpenBot策略与驱动契约</td></tr><tr><td>接管、交还、新观察和停止旧输入</td><td>OpenBot Computer Use</td></tr><tr><td>身份、记忆、任务与审计</td><td>OpenBot持久层</td></tr></tbody></table><p>只读查看当前打包的驱动描述，不调用模型：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const d=require(&quot;./src/agent-driver&quot;); for(const id of [&quot;dsh&quot;,&quot;pi&quot;,&quot;legacy&quot;]) console.log(d.describeAgentDriver(id))&#39;</span></span></code></pre></div><p>显式配置 <code>OPENBOT_AGENT_ENGINE=legacy</code> 可改变未单独保存内核的Bot默认值；Bot已明确选择的内核保持。源码入口为 <code>src/agent-driver.js</code>、<code>src/dsh-agent.js</code>、<code>src/pi-agent.js</code> 与 <code>src/tools.js</code>。</p><h2 id="dsh-四层概念、五态能力真值与受控桥接-源码演进候选" tabindex="-1">DSH 四层概念、五态能力真值与受控桥接（源码演进候选） <a class="header-anchor" href="#dsh-四层概念、五态能力真值与受控桥接-源码演进候选" aria-label="Permalink to &quot;DSH 四层概念、五态能力真值与受控桥接（源码演进候选）&quot;">​</a></h2><p>为消除用户与插件作者对 DSH 内部概念、L2 工具加速器与固定执行器边界（<code>D24</code>/<code>D25</code>）的混淆，Bot Studio 在隔离工作树引入了一组统一投影与受控桥接模块（当前属源码候选，<code>22</code> 项集成测试通过，尚未合入正式安装包）：</p><p><img src="'+r+'" alt="DSH 5+1 架构、四层概念与受控桥接"></p><h3 id="四层概念-×-三种交付通道" tabindex="-1">四层概念 × 三种交付通道 <a class="header-anchor" href="#四层概念-×-三种交付通道" aria-label="Permalink to &quot;四层概念 × 三种交付通道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>DSH 概念</th><th>Bot Studio 产品映射</th><th>交付通道规则</th><th>安全边界</th></tr></thead><tbody><tr><td><strong>Bundle（能力包）</strong></td><td>可分发插件/能力包</td><td>仅单步 <code>kind: &#39;bundle&#39;</code> 支持 <code>hub-auto-install</code>（dsh.fish），另有 <code>curated-manual</code> 与 <code>host-injected</code></td><td>目录配置严格保持 <code>{}</code>，禁止携带私钥或凭据</td></tr><tr><td><strong>Profile（装配档案）</strong></td><td>L4 Bot 装配身份与宿主设置</td><td>不支持自动 Hub 安装（<code>dshHubAutoInstallSupported: false</code>）</td><td>每 Bot 独立版本修订校验（<code>profileRevision</code>）与隔离空间</td></tr><tr><td><strong>Agent Preset（角色预设）</strong></td><td>编排 <code>HarnessPlan</code> 的运行时预设</td><td>仅作用于 <code>activeInPlan</code> 阶段</td><td>不跨执行器偷偷放权或重写绑定</td></tr><tr><td><strong>Workbench（工作台）</strong></td><td>从 <code>HarnessPlan</code> 投影出的确定性 <code>tool-panel</code></td><td>由主进程控制器直接编排（<code>0</code> 次 L1 LLM 网络调用）</td><td>强制 <code>workbenchRevision</code>（64 位十六进制）、动作幂等键与同修订审批绑定</td></tr></tbody></table><h3 id="d24-五态能力真值-effectivecapabilitymanifest" tabindex="-1"><code>D24</code> 五态能力真值（<code>EffectiveCapabilityManifest</code>） <a class="header-anchor" href="#d24-五态能力真值-effectivecapabilitymanifest" aria-label="Permalink to &quot;`D24` 五态能力真值（`EffectiveCapabilityManifest`）&quot;">​</a></h3><p>渲染层与用户界面从 <code>projectBotCapabilityManifest</code> 获取只读五态事实，杜绝把“插件已安装”误判为“当前 Bot 可用”：</p><ol><li><code>installed</code>：该能力包或工具是否真实安装在宿主清单中。</li><li><code>bound</code>：是否显式绑定到当前 Bot 的装配清单。</li><li><code>activeInPlan</code>：是否已进入当前运行时的 <code>HarnessPlan</code>。</li><li><code>invoked</code>：本轮或历史观察记录中是否真实被调用过。</li><li><code>blocked</code>：携带结构化阻塞码（如 Codex 固定执行器下显示 <code>DSH_PLUGIN_FLOW_UNAVAILABLE</code>、纯文本实例显示 <code>DSH_INSTANCE_TEXT_ONLY</code>、修订过期显示 <code>DSH_WORKBENCH_STALE</code>）；阻塞展示优先生效，但<strong>绝不擦除底层 <code>installed</code> 事实</strong>。</li></ol><h3 id="deepseek-l2-加速器与-codex-×-dsh-互补架构" tabindex="-1">DeepSeek L2 加速器与 Codex × DSH 互补架构 <a class="header-anchor" href="#deepseek-l2-加速器与-codex-×-dsh-互补架构" aria-label="Permalink to &quot;DeepSeek L2 加速器与 Codex × DSH 互补架构&quot;">​</a></h3><ul><li><strong>L2 加速器（<code>src/deepseek-l2-tools.js</code>）</strong>：封装 <code>/v1/tools/{search,fetch,ocr,asr,tts}</code> 与 <code>deepseek_web_search</code> / <code>deepseek_read_url</code> 内置工具，在宿主通过 <code>getApiKey</code> 实时注钥；公开清单与错误堆栈执行值级凭据扫描（<code>assertNoSecretLiterals</code>）、幂等脱敏（<code>redactSecrets</code>）、<code>redirect: &#39;error&#39;</code> 与私有 IP SSRF 阻断，以及响应体积与超时上限。</li><li><strong>Codex × DSH 受控桥接（<code>D25</code> 守卫）</strong>：Codex 类 Bot（<code>agent:codex</code>）绝不在进程内偷跑 <code>runDshAgent</code> 或调用 DSH 插件工作流；在每次桥接工具调用前重新执行 <code>assertFixedExecutorSelection</code>，仅开放宿主代理的 L2 感知工具（<code>l2_search</code>、<code>l2_fetch</code>、<code>l2_ocr</code>、<code>l2_asr</code>、<code>l2_tts</code>）和跨 Bot 异步委派工具 <code>delegate_to_dsh_bot</code>，由具备 DSH 能力的接收 Bot 执行后返回 <code>openbot.task-receipt/1</code> 回执。</li></ul><p><img src="'+c+'" alt="Bot Studio 六层融合全览"></p><p>继续阅读<a href="/openbot/guide/jarvis.html">主脑委派</a>、<a href="/openbot/guide/computer-use.html">浏览器工作屏幕</a>或<a href="/openbot/development/contributing.html">参与贡献</a>。</p>',33)])])}const _=t(s,[["render",i]]);export{g as __pageData,_ as default};
